dev.cloudroom.preview.9b3118c5330c14b8.plist

# A routing rule pointing at a missing path means the agent confidently walks
# into a wall. Cheap to check, so check every run.
Write-Head "Routing integrity (AGENTS.md backtick paths)"
$agents = Get-Content -Raw -LiteralPath (Join-Path $Root "AGENTS.md")
$dead = 0; $checked = 0
# Only judge paths this repo actually owns. A candidate qualifies when its first
# segment is a real top-level entry here. Everything else — external absolute
# paths, elided `…\x\y` forms, shell commands — is out of scope and is checked
# by `keystone paths` / `keystone health`, not here. A check that cries wolf on
# things it can't resolve gets ignored, which is worse than no check.
$topLevel = @(Get-ChildItem $Root -Force | ForEach-Object { $_.Name })
foreach ($m in [regex]::Matches($agents, '`([^`]+)`')) {
    $cand = $m.Groups[1].Value.Trim()
    if ($cand -match '…|\*|<|>|\||^\.\\|^[A-Za-z]:\\' -or $cand -match '^\S+\s') { continue }
    $first = ($cand -replace '/', '\').Split('\')[0]
    if ($topLevel -notcontains $first) { continue }
    $checked++
    $full = Join-Path $Root ($cand -replace '/', '\')
    if (-not (Test-Path -LiteralPath $full)) {
        $issues.Add("DEAD ROUTE: AGENTS.md points at '$cand' which does not exist")
        Write-Host "  DEAD: $cand" -ForegroundColor Red
        $dead++
    }
}
if ($dead -eq 0) { Write-Host "  all $checked in-repo routes resolve" -ForegroundColor DarkGray }

# --- 3. Unmapped top-level surfaces ----------------------------------------
# Unmapped means invisible to a fresh session.
Write-Head "Unmapped top-level surfaces"
$unmapped = 0
foreach ($d in Get-ChildItem $Root -Directory | Where-Object { $_.Name -notmatch '^\.' }) {
    if ($agents -notmatch [regex]::Escape($d.Name)) {
        $issues.Add("UNMAPPED: top-level '$($d.Name)\' is not mentioned in AGENTS.md")
        Write-Host "  UNMAPPED: $($d.Name)\" -ForegroundColor Yellow
        $unmapped++
    }
}
if ($unmapped -eq 0) { Write-Host "  every top-level folder is routed" -ForegroundColor DarkGray }

